#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <chrono>
int main(){try{SessionTimelineDocumentCandidate doc(loadGraph("work/roundtrip-11.dmx"));auto original=doc.frameCount();if(doc.dirty())throw std::runtime_error("initial dirty");doc.setDuration(10000);if(doc.frameCount()!=60||!doc.dirty())throw std::runtime_error("duration edit");if(doc.undo()!=1||doc.frameCount()!=original||doc.dirty())throw std::runtime_error("undo");if(doc.redo()!=1||doc.frameCount()!=60||!doc.dirty())throw std::runtime_error("redo");bool rejected=false;try{doc.setDuration(-1);}catch(const std::runtime_error&){rejected=true;}if(!rejected||doc.frameCount()!=60)throw std::runtime_error("invalid edit changed state");auto path="work/timeline-document-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".dmx";doc.saveAs(path.c_str());SessionTimelineDocumentCandidate loaded(loadGraph(path.c_str()));if(loaded.frameCount()!=60||doc.dirty())throw std::runtime_error("save reload");rejected=false;try{doc.saveAs(path.c_str());}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("overwrite allowed");doc.undo();if(!doc.dirty())throw std::runtime_error("savepoint dirty");doc.setDuration(20000);if(doc.redo()!=0||doc.frameCount()!=120)throw std::runtime_error("redo branch retained");std::cout<<"timeline document passed duration_edit undo redo invalid_atomic save_reload no_overwrite savepoint_dirty branch_redo_clear original_frames="<<original<<" output="<<path<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
